            var world = JsonUtility.FromJson<Terra.Contracts.WorldData>(System.IO.File.ReadAllText("worlds/meadowbrook-v1/world.json"));
            var scenario = JsonUtility.FromJson<Terra.Contracts.Scenario>(System.IO.File.ReadAllText("worlds/meadowbrook-v1/scenario.json"));
            var definition = Terra.Core.AnnualTownDemo.FromWorldPack(world, scenario, "meadowbrook-v1");
            var go = new GameObject("Hosted chapter fallback checks");
            try
            {
                var town = go.AddComponent<Terra.Gameplay.AnnualTownSession>();
                town.Initialize(definition, "hosted-fallback-checks");
                var offer = definition.actions.First(a => town.Preview(a.siteId, a.actionId) >= 0);
                town.QueueAction(offer.siteId, offer.actionId, town.State.revision);
                town.BeginYear("hosted-fallback-year-1", town.State.revision);
                var input = new Terra.Contracts.AnnualChapterRequest { definition = town.Definition, snapshot = town.State };
                var chapters = go.AddComponent<Terra.Gameplay.AnnualChapterSession>(); chapters.town = town; chapters.autoSave = false;
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                var frozen = typeof(Terra.Gameplay.AnnualChapterSession).GetField("frozen", flags);
                var fail = typeof(Terra.Gameplay.AnnualChapterSession).GetMethod("Fail", flags);
                var readyForFallback = typeof(Terra.Gameplay.AnnualChapterSession).GetField("readyForFallback", flags);
                var expected = Terra.Core.AnnualChapters.Preview(input).Snapshot();
                frozen.SetValue(chapters, input);
                fail.Invoke(chapters, new object[] { "Synthetic save failure before networking" });
                Check(town.State.phase == Terra.Contracts.TownPhase.Resolving && town.State.history.Length == 0, "A pre-network save failure advanced the year.");
                frozen.SetValue(chapters, input); readyForFallback.SetValue(chapters, true);
                fail.Invoke(chapters, new object[] { "Synthetic provider quota reached" });
                Check(town.State.phase == Terra.Contracts.TownPhase.Reviewing && town.State.history.Length == 1, "Fallback must accept exactly one year.");
                Check(town.State.cashCents == expected.cashCents, "Fallback changed the reconciled cash.");
                Check(JsonUtility.ToJson(town.State.history[0]) == JsonUtility.ToJson(expected.history[0]), "Fallback changed engine outcomes.");
                Check(chapters.Latest.mode == "offline" && chapters.Latest.chapter.introduction.StartsWith("AI unavailable."), "Fallback disclosure missing.");
                Check(!chapters.Busy && chapters.Error == null, "Fallback left a busy/error state.");
                var saved = chapters.ExportSave();
                chapters.ResolveOffline();
                Check(chapters.ExportSave() == saved, "Repeated resolution changed the accepted year.");
                chapters.ImportSave(saved);
                Check(chapters.ExportSave() == saved, "Fallback receipt did not survive save/reload exactly.");
                chapters.ImportSave(JsonUtility.ToJson(new Terra.Contracts.AnnualChapterSave { town = input.snapshot, chapters = Array.Empty<Terra.Contracts.AnnualChapterReceipt>() }));
                chapters.fallbackWhenUnavailable = false; frozen.SetValue(chapters, input); readyForFallback.SetValue(chapters, true);
                fail.Invoke(chapters, new object[] { "Synthetic transport failure" });
                Check(town.State.phase == Terra.Contracts.TownPhase.Resolving && town.State.history.Length == 0, "Disabled fallback advanced the year.");
                Check(!string.IsNullOrEmpty(chapters.Error), "Disabled fallback lost recovery information.");
                chapters.fallbackWhenUnavailable = true;
                frozen.SetValue(chapters, input); readyForFallback.SetValue(chapters, true); fail.Invoke(chapters, new object[] { "Synthetic timeout" });
                Check(town.State.history.Length == 1 && town.State.cashCents == expected.cashCents, "Retry rerolled the pending year.");
            }
            finally { UnityEngine.Object.DestroyImmediate(go); }

